/**
 * Archiving a project freezes its issues, their comments and attachments:
 * every write under one is refused, while reads keep working. Callers run
 * this after their permission check and their own archived-row check, so
 * those errors keep their precedence.
 */
export async function assertProjectNotArchived(
  orgId: OrgId,
  issue: Issue,
): Promise<void> {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, issue.projectId),
    "Project",
    issue.projectId,
  );
  if (isArchived(project)) {
    throw new AlreadyArchivedError("Project", project.id);
  }
}

